class FixedOffset(tzinfo):
    def __init__(self, offset_minutes):
        self._offset = timedelta(minutes=offset_minutes)
    def utcoffset(self, dt):
        return self._offset
    def tzname(self, dt):
        return ""
    def dst(self, dt):
        return None

from datetime import timedelta

def parse_ts(s):
    """Parse ISO 8601 timestamp to a datetime in UTC."""
    s = s.strip()
    # Handle Z suffix
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'

    # Try parsing with timezone offset ±HH:MM or ±HHMM
    m = re.match(r'(.+?)([+-])(\d{2}):?(\d{2})$', s)
    if m:
        base_str, sign, hh, mm = m.groups()
        offset_minutes = int(hh) * 60 + int(mm)
        if sign == '-':
            offset_minutes = -offset_minutes
        tz = FixedOffset(offset_minutes)
        # Try various formats
        for fmt in ('%Y-%m-%dT%H:%M:%S.%f', '%Y-%m-%dT%H:%M:%S'):
            try:
                dt = datetime.strptime(base_str, fmt).replace(tzinfo=tz)
                return dt.astimezone(timezone.utc)
            except ValueError:
                continue
