        return None

    ts = parse_ts(str(ts_raw))
    if ts is None:
        return None

    # Parse status
    try:
        status_val = int(status)
    except (ValueError, TypeError):
        return None

    # Parse latency_ms - can be number or string like "412ms"
    lat_str = str(latency).strip()
    m = re.match(r'^(\d+)(?:ms)?$', lat_str)
    if not m:
        try:
            latency_val = int(latency)
        except (ValueError, TypeError):
            return None
    else:
        latency_val = int(m.group(1))

    return {
        'ts': ts,
        'user': user.lower(),
        'request_id': str(req_id),
        'status': status_val,
        'latency_ms': latency_val
    }

