def compute_p95(values):
    """Compute p95 using nearest-rank method."""
    n = len(values)
    if n == 0:
        return 0
    rank = math.ceil(0.95 * n)  # 1-based
    return values[rank - 1]

def main():
    if len(sys.argv) < 2:
        print("Usage: python3 p95.py LOGDIR", file=sys.stderr)
        sys.exit(1)

    logdir = sys.argv[1]

    if not os.path.isdir(logdir):
        print("Error: directory does not exist", file=sys.stderr)
        sys.exit(1)

    all_records = {}  # request_id -> best record (latest timestamp)

    for fname in sorted(os.listdir(logdir)):
        fpath = os.path.join(logdir, fname)
        if not os.path.isfile(fpath):
            continue

        match = re.match(r'^app\.log(\.(\d+)(\.gz)?)?$', fname)
        if not match:
            continue

        lines = read_file_lines(fpath)
        for line in lines:
            record = parse_line(line)
            if record is None:
                continue

            req_id = record['request_id']

            # Keep only the latest timestamp for each request_id
            if req_id not in all_records or record['ts'] > all_records[req_id]['ts']:
                all_records[req_id] = record

    # Group failures by user
    user_failures = {}  # user -> list of latency_ms values
    for req_id, rec in all_records.items():
        if rec['status'] >= 500:
            user = rec['user']
            if user not in user_failures:
                user_failures[user] = []
            user_failures[user].append(rec['latency_ms'])

    # Compute p95 for each user with failures
    rows = []
    for user, latencies in user_failures.items():
        if len(latencies) > 0:
            sorted_lats = sorted(latencies)
            p95 = compute_p95(sorted_lats)
            rows.append((user, len(latencies), int(p95)))

    # Sort by failures desc, then user asc
    rows.sort(key=lambda x: (-x[1], x[0]))

    # Output CSV
    print("user,failures,p95_ms")
    for user, failures, p95 in rows:
        print(f"{user},{failures},{p95}")

if __name__ == '__main__':
    main()
